//! Build-time codegen for `recipes.json`: dump order kept, maps sorted by
//! key like the old reader. A null row renders the old defaults.

/// Render `recipes_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "recipes");
    let rows = crate::dump_rows(&parsed, "recipes");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/recipes.json - do not edit.\n\
         pub static ALL: &[super::StaticRecipe] = &[\n",
    );
    for row in rows {
        generated.push_str(&format!(
            "    super::StaticRecipe {{ kind: \"{}\", level: {}, xp: {}, inputs: {}, outputs: {}, \
             source: \"{}\", burnt: {}, members: {} }},\n",
            crate::escape_for_rust_literal(row.get("kind").as_str().unwrap_or("")),
            row.get("level").as_i64().unwrap_or(0),
            row.get("xp").as_i64().unwrap_or(0),
            crate::render_str_int_map(row, "inputs"),
            crate::render_str_int_map(row, "outputs"),
            crate::escape_for_rust_literal(row.get("extra").get("row").as_str().unwrap_or("")),
            crate::render_opt_str(row.get("extra").get("burnt")),
            crate::render_opt_flag(row, "members"),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("recipes_generated.rs", &generated);
}
